#! /usr/bin/env python3
# This script generates Lib/re/_casefix.py.

import collections
import sys
import unicodedata

SCRIPT_NAME = 'Tools/build/generate_re_casefix.py'

def update_file(file, content):
    try:
        with open(file, encoding='utf-8') as fobj:
            if fobj.read() == content:
                return False
    except (OSError, ValueError):
        pass
    with open(file, 'w', encoding='utf-8') as fobj:
        fobj.write(content)
    return True

re_casefix_template = f"""\
# Auto-generated by {SCRIPT_NAME}.
#
# Every character which has to be matched case-insensitively with another one
# is folded to the same code by sre_lower_unicode(), so this module has no
# tables; the script checks that this holds.
"""

def uname(i):
    return unicodedata.name(chr(i), r'U+%04X' % i)

class hexint(int):
    def __repr__(self):
        return '%#06x' % self

def alpha(i):
    c = chr(i)
    return c if c.isalpha() else ascii(c)[1:-1]


def main(outfile='Lib/re/_casefix.py'):
    import _sre

    # Characters which case fold to the same string, or which have the same
    # uppercase, are matched case-insensitively, so sre_lower_unicode() has to
    # fold them to the same code -- by the case folding, or by one of the few
    # exceptions which it hardcodes.
    equivalent_chars = collections.defaultdict(str)
    for c in map(chr, range(sys.maxunicode + 1)):
        equivalent_chars['f' + c.casefold()] += c
        equivalent_chars['u' + c.upper()] += c
    not_folded = sorted(t for s in equivalent_chars.values() if len(s) > 1
                        for t in [sorted({_sre.unicode_tolower(ord(c))
                                          for c in s})]
                        if len(t) > 1)
    if not_folded:
        print('Case-insensitive matching does not work for characters:',
              file=sys.stderr)
        for t in not_folded:
            print('  ' + ', '.join("'%s' (U+%04x, %s)" % (alpha(i), i, uname(i))
                                   for i in t), file=sys.stderr)
        sys.exit(1)

    update_file(outfile, re_casefix_template)

if __name__ == '__main__':
    import sys
    main(*sys.argv[1:])
